import sprite from "./flags/flags.webp";
import flags from "./flags/flags.json";

// One WebP sprite (~95 KB, generated by scripts/gen-flag-sprite.mjs from
// flag-icons, MIT) holds every flag at 3x density. Flags look the same on
// every platform (Windows has no flag emoji) and cost a single request,
// made only once a flag is on screen.
const index = new Map(flags.codes.map((code, i) => [code, i]));
const WIDTH = 16, HEIGHT = 12;
const scale = WIDTH / flags.width;
const backgroundSize = `${flags.columns * WIDTH}px ${Math.ceil(flags.codes.length / flags.columns) * HEIGHT}px`;

export function hasCountryFlag(code: string) {
  return index.has(code.toUpperCase());
}

/** A small decorative flag; the country name next to it carries the meaning. */
export function CountryFlag({ code, className = "" }: { code: string; className?: string }) {
  const i = index.get(code.toUpperCase());
  if (i === undefined) return null;
  const x = (i % flags.columns) * flags.width * scale;
  const y = Math.floor(i / flags.columns) * flags.height * scale;
  return <span aria-hidden="true" data-flag={code.toUpperCase()}
    className={`inline-block h-3 w-4 shrink-0 rounded-[2px] align-[-1px] shadow-[0_0_0_1px_var(--border)] ${className}`}
    style={{ backgroundImage: `url(${sprite})`, backgroundSize, backgroundPosition: `-${x}px -${y}px`, backgroundRepeat: "no-repeat" }} />;
}
